const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("bcc_rpc_response_topic", msg.rpcResponseTopic);
flow.set("bcc_write_result", msg.writeResult || null);

// Clear partial data
flow.set("bcc_part_capacity", null);
flow.set("bcc_part_current", null);

return msg;

msg.baseAddr = 202;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 202,
    quantity: 1
};
return msg;

msg.baseAddr = 208;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 208,
    quantity: 2
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    node.error("Invalid modbus response");
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    return null;
}

// Store partial data based on baseAddr
if (baseAddr === 202) {
    flow.set("bcc_part_capacity", {
        batteryCapacityAh: data[0] || 0
    });
}
else if (baseAddr === 208) {
    flow.set("bcc_part_current", {
        maxChargeCurrentA: data[0] || 0,
        maxDischargeCurrentA: data[1] || 0
    });
}
else {
    return null;
}

// Check if all parts are ready
const capacityPart = flow.get("bcc_part_capacity");
const currentPart = flow.get("bcc_part_current");

if (!capacityPart || !currentPart) {
    return null; // Wait for all parts
}

// Build final state
const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "BatteryCapacityConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    batteryCapacityAh: capacityPart.batteryCapacityAh,
    maxChargeCurrentA: currentPart.maxChargeCurrentA,
    maxDischargeCurrentA: currentPart.maxDischargeCurrentA
};

// Clear partials
flow.set("bcc_part_capacity", null);
flow.set("bcc_part_current", null);

// Get write result and rpc topic
const writeResult = flow.get("bcc_write_result");
const rpcResponseTopic = flow.get("bcc_rpc_response_topic");

flow.set("bcc_write_result", null);
flow.set("bcc_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

// Parse RPC params and build write queue
const params = msg.rpcParams || {};

const writes = [];

// Register 202: Battery Capacity (Ah) [0-2000]
if (params.batteryCapacityAh !== undefined) {
    const val = params.batteryCapacityAh;
    if (val < 0 || val > 2000) {
        node.error("batteryCapacityAh must be 0-2000");
    } else {
        writes.push({ register: 202, value: val, name: "Battery Capacity" });
    }
}

// Register 208: Max Charge Current (A) [0-185]
if (params.maxChargeCurrentA !== undefined) {
    const val = params.maxChargeCurrentA;
    if (val < 0 || val > 185) {
        node.error("maxChargeCurrentA must be 0-185");
    } else {
        writes.push({ register: 208, value: val, name: "Max Charge Current" });
    }
}

// Register 209: Max Discharge Current (A) [0-185]
if (params.maxDischargeCurrentA !== undefined) {
    const val = params.maxDischargeCurrentA;
    if (val < 0 || val > 185) {
        node.error("maxDischargeCurrentA must be 0-185");
    } else {
        writes.push({ register: 209, value: val, name: "Max Discharge Current" });
    }
}

// No writes? Just do read
if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("bcc_write_queue", writes);
global.set("bcc_write_index", 0);
global.set("bcc_write_results", []);
global.set("bcc_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("bcc_write_queue") || [];
const index = global.get("bcc_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("bcc_write_queue") || [];
let index = global.get("bcc_write_index") || 0;
const results = global.get("bcc_write_results") || [];

// Record success
const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("bcc_write_results", results);
}

// Move to next
index++;
global.set("bcc_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

// More writes?
if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done - go to read
const rpcTopic = global.get("bcc_write_rpc_topic");

global.set("bcc_write_queue", null);
global.set("bcc_write_index", null);
global.set("bcc_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

global.set("bcc_write_results", null);

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
